



# =====================================================================
# THE CELLS OF THE DEATH, I — F1 the ascent and the land shown (34:1-3), F2 the oath and the denial (34:4) — each ask a case; the verdicts DATA rows or PARAMETERS, never the ink's
# =====================================================================
D1 = "Moses' last day (40, 12, 7) — 19b's marker at 31:1, no marker here; the thirty days a duration"
def SV(x, n=60):
    """a callee's value as a short string — a tuple's verdict, a q-cell's v, a DATA row's value (the print decides the literal)"""
    y = x[0] if isinstance(x, tuple) else (x.get('v') if isinstance(x, dict) and 'v' in x else (x.get('value') if isinstance(x, dict) and 'value' in x else x))
    return str(y)[:n]
def the_ascent_and_the_land_shown(case, data):
    """F1 — Deut 34:1-3 — ONE LINE moses_went_up_to_nebo_and_saw_the_land (ACT — the ascent) writing moses_went_up_to_nebo_as_commanded and the_whole_land_shown_to_moses_gilead_to_zoar (STATUSES on Moses); 32:49's summons OBEYED by CALL (song_charge_nebo — a RUN CITATION), 3:27's Pisgah refused then granted (opening_speech by CALL), Reuben's Nebo (gad_reuben by CALL), 'as far as Dan' Genesis 14:14's (mamre by CALL); 357:1-25 THE LAND SHOWN AS THE FUTURE (Sanhedrin 10:1 the case — the world to come's share); the Prophets' and the Writings' seats cited never read"""
    del P_[:]
    ask = case['ask']
    if ask == 'and_moses_went_up_from_the_plains_of_moab_to_mount_nebo_the_top_of_pisgah_over_against_jericho':
        ink('34:1', "'AND MOSES WENT UP FROM THE PLAINS OF MOAB TO MOUNT NEBO, THE TOP OF PISGAH, OVER AGAINST JERICHO' — 32:49's command obeyed word for word (the kin computed %s; the twin diffed %d — 'over against Jericho' four in order; 'Mount Nebo' and 'over against Jericho' these two seats alone in the Bible: %s); 3:27's 'the top of Pisgah' (the twin %d); 'and Moses went up' five in the Bible — Sinai's four ascents and this last; 357:1 AN ASCENT AND NOT A DESCENT" % (KINC[(34, 1)][0], TWIN['34:1 vs 32:49'], P(_G('הר (mount)'), _G('נבו (Nebo)'), books=None), TWIN['34:1 vs 3:27']))
        move("cold_run_song_charge_nebo (CALL) — SC.the_summons_to_nebo(go_up_into_this_mountain_of_abarim_mount_nebo_and_behold_the_land_of_canaan) = %s (the command on the tape — go_up_to_nebo_see_the_land_commanded on moses: THE RUN CITATION); cold_run_opening_speech (CALL) — OS.the_plea(pisgah) = %s (3:27's Pisgah refused, granted here); cold_run_gad_reuben (CALL) — GR.DATA moses_grave = %s (Reuben's Nebo, Gad's field — Numbers 32:38)" % (SV(SC_GOUP, 60), SV(OS_PISGAH, 50), SV(GR_GRAVE, 40)), "the summons obeyed the day it was given — 32:48's 'that selfsame day' and 34:1's ascent one day, Moses' last (Onkelos 'the head of the height'); THE WRITE moses_went_up_to_nebo_as_commanded — a STATUS on moses (DP2), the ascent's ACT at Moses' last day, NO MARKER")
        dat("THE LINE moses_went_up_to_nebo_and_saw_the_land (an ACT) at %s; THE WRITE moses_went_up_to_nebo_as_commanded, a STATUS on moses; the readback row 34:1 SUPPLIED with its writes and REFERENCE against the summons by kind (nebo_summons_die_as_aaron at 32:48)" % D1)
        return out("and Moses went up from the plains of Moab to Mount Nebo, the top of Pisgah, over against Jericho (34:1) — 32:49's command obeyed word for word (the summons on the tape by CALL: %s): THE WRITE moses_went_up_to_nebo_as_commanded, a STATUS on Moses; an ascent and not a descent (357:1), at Moses' last day" % (SV(SC_GOUP, 40),), ['moses_went_up_to_nebo_as_commanded'])
    if ask == 'the_lord_showed_him_all_the_land_gilead_to_dan_naphtali_ephraim_and_manasseh_judah_to_the_hinder_sea':
        ink('34:1-2', "'AND THE LORD SHOWED HIM ALL THE LAND, Gilead as far as Dan, and all Naphtali, and the land of Ephraim and Manasseh, and all the land of Judah as far as the hinder sea' — 'and the LORD showed him' once in the Bible; 'as far as Dan' Genesis 14:14's phrase (%s — Abraham's pursuit, the kin by the ink's word); 'the hinder sea' 11:24's (the twin %d; Onkelos THE WESTERN SEA); the store's 'Daniel' for Dan the border patched by gloss" % (P(_G('עד (as far as)'), _G('דן (Dan)'), books=T), TWIN['34:2 vs 11:24']))
        move("cold_run_mamre (CALL) — MA.abraham_end(seed_multiplied_closed) = %s (the promise to Abraham — the land shown to his seed's lawgiver); cold_run_gad_reuben (CALL) — GR.DATA deaths_ceased = %s (the generation's end on the tape; the land east the tape's); 357:1-25 THE LAND SHOWN AS THE FUTURE — Gilead and Samson, Dan and Barak, Naphtali and Joshua, Ephraim and Gideon, Manasseh, Judah and David, the hinder sea THE LAST DAY (357:10-11 — the world to its end and the resurrection: MISHNAH SANHEDRIN 10:1 THE CASE, the parameter the_world_to_come_share); the Prophets' and the Writings' seats cited never read" % (SV(MA_SEED, 40), SV(GR_CEASED, 30)), "THE WRITE the_whole_land_shown_to_moses_gilead_to_zoar — a STATUS on moses; THE DATA ROW the_land_shown_as_the_future (no law, no write beyond the statuses on moses)")
        dat("THE WRITE the_whole_land_shown_to_moses_gilead_to_zoar, a STATUS on moses at %s; THE DATA ROW the_land_shown_as_the_future; THE PARAMETER the_world_to_come_share — MISHNAH SANHEDRIN 10:1 THE CASE at 357:10-11; the readback row 34:2 VERBATIM" % D1)
        return out("and the LORD showed him all the land, Gilead as far as Dan, Naphtali, Ephraim and Manasseh, Judah as far as the hinder sea (34:1-2) — the land shown as the future, each land with its judge or king, the hinder sea the last day (357:1-25; Sanhedrin 10:1 the case): THE WRITE the_whole_land_shown_to_moses_gilead_to_zoar, a STATUS on Moses; the Prophets' seats cited never read", ['the_whole_land_shown_to_moses_gilead_to_zoar'])
    if ask == 'the_south_and_the_plain_the_valley_of_jericho_the_city_of_palms_to_zoar':
        ink('34:3', "'and the South, and the Plain, the valley of Jericho, the city of palms, as far as Zoar' — 'the valley of Jericho' once in the Bible; 'the city of palms' three seats (%s — 2 Chronicles 28:15 and Judges 3:13 cited never read; the twin %d); 'as far as Zoar' Isaiah 15:5's twin (cited never read); Onkelos 'the South', 'the Plain', 'the city of PALMS' (the store's 'the-circle' and 'the-palm-tree' patched by gloss); the kin computed %s" % (P(_G('עיר (the city of)'), _G('התמרים (the palms)'), books=None), TWIN['34:3 vs 2Chr 28:15'], KINC[(34, 3)][0]))
        move("357:12-25 the South and the Plain — Machpelah's cave (the fathers' grave: cold_run_family (CALL) — FA.purchase(possession_by_burial) = %s), Solomon's vessels, Gog and Magog, Eden and Gehenna (the Writings' seats cited never read); Zoar Lot's refuge (Genesis 19 — mamre's Sodom by reference)" % (SV(FA_POSS, 50),), "the catalogue inside the line — NO WRITE (the two statuses on moses the line's); the readback row 34:3 VERBATIM")
        dat("the south, the plain, the valley of Jericho, the city of palms, Zoar — the last of the land shown; no write (the catalogue inside the line); the readback row 34:3 VERBATIM; the Writings' and the Prophets' seats (2 Chronicles 28:15, Judges 3:13, Isaiah 15:5) cited never read")
        return out("the South and the Plain, the valley of Jericho, the city of palms, as far as Zoar (34:3) — the last of the land shown, Machpelah's cave among the places (357:12-25); no write, the catalogue inside the line; the Writings' seats cited never read", ['accepted'])
    return 'no verdict in span', [], list(P_)

def the_oath_and_the_denial(case, data):
    """F2 — Deut 34:4 — ONE LINE oath_land_shown_not_crossed_declared (SPEECH of the LORD — the subject god) writing land_sworn_to_the_fathers_shown_at_the_end_declared (a STATUS on Moses) and REUSING see_the_land_from_afar_not_go_there at 34:4 on Moses (a HEAVEN entry — THE SONG'S OWED POINTER PAID, the readback's POINTER ROW 34:4); EXODUS 33:1's LINE TAKEN WHOLE (erection by CALL — a RUN CITATION), the three fathers (hear_o_israel, mamre by CALL), the commission's debit PAID (opening_speech by CALL), the two denials (song_charge_nebo by CALL — 341:1 and 357:27 by I2)"""
    del P_[:]
    ask = case['ask']
    if ask == 'this_is_the_land_which_i_swore_to_abraham_to_isaac_and_to_jacob_saying_to_your_seed_i_will_give_it':
        ink('34:4', "'AND THE LORD SAID TO HIM: THIS IS THE LAND WHICH I SWORE TO ABRAHAM, TO ISAAC AND TO JACOB, SAYING: TO YOUR SEED I WILL GIVE IT' — EXODUS 33:1's LINE TAKEN WHOLE: the kin computed %s, the twin diffed %d (NINE IN ORDER — the land which I swore to Abraham, to Isaac and to Jacob, saying: to your seed I will give it); 'to your seed I will give it' these two seats alone in the Bible (%s); the three fathers 6:10's (the twin %d); the chapter's one 'he said' and its one 'saying'; the first person at 34:4 alone (I swore, I will give it, I have caused you to see)" % (KINC[(34, 4)][0], TWIN['34:4 vs Exod 33:1'], P(_G('לזרעך (to your seed)'), _G('אתננה (I will give it)'), books=None), TWIN['34:4 vs 6:10']))
        move("cold_run_erection (CALL) — ER.tablets(breaking_ratified) = %s (Exodus 32-34's aftermath on the tape — 33:1's 'to your seed I will give it' the LORD's words after the calf: THE RUN CITATION, said again at the end); cold_run_hear_o_israel (CALL) — HI.DATA the_oath_by_the_name = %s (6:10's three fathers; 6:13's swearing by the Name); cold_run_mamre (CALL) — MA.abraham_end(promise_closed_here) = %s (Genesis 12:7 and 15:18's promise to Abraham — the roots); 357:26 the oath shown at the end" % (SV(ER_BREAK, 50), SV(HI_OATH, 50), SV(MA_PROMISE, 40)), "Onkelos 'which I SWORE … to your SONS I will give it' (the seed rendered the sons); THE WRITE land_sworn_to_the_fathers_shown_at_the_end_declared — a STATUS on moses (DP2); THE DATA ROW the_oath_is_exodus_33_1")
        dat("THE LINE oath_land_shown_not_crossed_declared (a SPEECH of the LORD — the subject god, 20b's form) at %s; THE WRITE land_sworn_to_the_fathers_shown_at_the_end_declared, a STATUS on moses; THE DATA ROW the_oath_is_exodus_33_1; the readback row 34:4 SUPPLIED with its write — THE POINTER ROW (grade R)" % D1)
        return out("this is the land which I swore to Abraham, to Isaac and to Jacob, saying: to your seed I will give it (34:4) — Exodus 33:1's line taken whole, nine tokens in order, the LORD's words after the calf said again at the end (the tape's own line by CALL: %s): THE WRITE land_sworn_to_the_fathers_shown_at_the_end_declared, a STATUS on Moses" % (SV(ER_BREAK, 40),), ['land_sworn_to_the_fathers_shown_at_the_end_declared'])
    if ask == 'i_have_caused_you_to_see_it_with_your_eyes_but_you_shall_not_cross_over_there':
        ink('34:4', "'I HAVE CAUSED YOU TO SEE IT WITH YOUR EYES, BUT YOU SHALL NOT CROSS OVER THERE' — THE TWO DENIALS: 32:52's 'there you shall not go' (the twin %d — 'there' the one shared token with the suffix) and 34:4's 'you shall not cross over there' (once in the Bible); 3:27's 'you shall not cross this Jordan' two in order (the twin %d); 'I have caused you to see' once in the Bible; the second person singular at 34:4 alone (four tokens)" % (TWIN['34:4 vs 32:52'], TWIN['34:4 vs 3:27']))
        move("cold_run_song_charge_nebo (CALL) — SC.meribah_and_the_seeing(you_shall_see_the_land_before_you_but_there_you_shall_not_go) = %s (32:52's denial on the tape — see_the_land_from_afar_not_go_there on moses, a HEAVEN entry: REUSED HERE at its own forward seat — THE SONG'S OWED POINTER PAID); cold_run_opening_speech (CALL) — OS.the_commission(the_debit) = %s (Numbers 27:12-13's 'see the land' — the debit PAID by the seeing, the denial its other arm); 341:1 and 357:27 read the two denials WORD FOR WORD as king and commoner, living and dead (I2 — the verbal analogy of the two 'there's); the angel of death refused (305:5)" % (SV(SC_DENIAL, 60), SV(OS_DEBIT, 50)), "Onkelos 'THITHER you shall not cross'; THE REUSE see_the_land_from_afar_not_go_there at 34:4 on moses (the second entry — the song's 32:52 the first; a heaven entry); THE POINTER ROW 34:4 grade R; barred_from_the_land 2 on moses and aaron UNMOVED — read, not rewritten (chukat.meribah by CALL)")
        dat("THE REUSE see_the_land_from_afar_not_go_there at 34:4 on moses (REUSE_AFTER 2 — the tape's print decides); THE POINTER ROW 34:4 (the song's owed pointer PAID, grade R); THE DATA ROW the_pointers_paid; the commission's debit PAID — a run citation (opening_speech by CALL: %s)" % (SV(OS_DEBIT, 40),))
        return out("I have caused you to see it with your eyes, but you shall not cross over there (34:4) — the two denials read as king and commoner, living and dead (341:1, 357:27 by I2): THE SONG'S OWED POINTER PAID — see_the_land_from_afar_not_go_there REUSED at its own forward seat on Moses (the song's line by CALL: %s), THE POINTER ROW 34:4 grade R; the commission's debit paid by the seeing" % (SV(SC_DENIAL, 40),), ['see_the_land_from_afar_not_go_there'])
    return 'no verdict in span', [], list(P_)
